 "content": "def transform(grid):
    # The scene consists of isolated horizontal bars on a uniform background.
    # Encode the number of bars of each marked color in a 2x3 count board,
    # listing color 3 first, then color 2, with remaining cells as zero.
    counts = {3: 0, 2: 0}
    for row in grid:
        i = 0
        while i < len(row):
            color = row[i]
            if color in counts:
                counts[color] += 1
                while i < len(row) and row[i] == color:
                    i += 1
            else:
                i += 1
    values = [3] * counts[3] + [2] * counts[2]
    values = (values + [0] * 6)[:6]
    return [values[:3], values[3:]]
